def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate 4-connected background regions; a region not reaching the edge is
    # an enclosed cavity. Its boundary identifies the 1-components to decorate.
    seen0 = set()
    cavities = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen0:
                continue
            q = [(r, c)]
            seen0.add((r, c))
            cells = []
            touches_edge = False
            while q:
                x, y = q.pop()
                cells.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    touches_edge = True
                for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= a < h and 0 <= b < w and grid[a][b] == 0
                            and (a, b) not in seen0):
                        seen0.add((a, b))
                        q.append((a, b))
            if not touches_edge:
                cavities.append(cells)

    # Qualify every 1-component bordering at least one enclosed cavity.
    seen1 = set()
    qualified = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen1:
                continue
            q = [(r, c)]
            seen1.add((r, c))
            comp = []
            while q:
                x, y = q.pop()
                comp.append((x, y))
                for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= a < h and 0 <= b < w and grid[a][b] == 1
                            and (a, b) not in seen1):
                        seen1.add((a, b))
                        q.append((a, b))
            if any((x + dx, y + dy) in set(cells)
                   for cells in cavities for x, y in comp
                   for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1))):
                qualified.update(comp)

    # Paint the one-cell rim: 3 on the cavity side and 2 on the exterior side.
    cavity_cells = {cell for cavity in cavities for cell in cavity}
    for x, y in qualified:
        for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
            if not (0 <= a < h and 0 <= b < w) or grid[a][b] != 0:
                continue
            if (a, b) in cavity_cells:
                out[a][b] = 3
            else:
                out[a][b] = 2
    return out
